cat > src/server/services/api-token-service.ts <<'EOF'
/**
 * Personal API tokens: minting, listing, revoking and turning a bearer secret back into an `Actor`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hashToken, randomToken, resolveActor
 */
import { emit } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createApiTokenSchema } from "@/schemas/api-token";
import { toIsoTimestamp } from "@/types/common";
import {
  actorEnvelope,
  apiTokenRevokedPayload,
  orgResource,
  requireFound,
} from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Every secret starts with this, so a leaked one is recognisable on sight. */
const SECRET_PREFIX = "tfk_";

/** Length in bytes of the random part of a secret. */
const SECRET_BYTES = 32;

/** How many characters of the secret are kept, in the clear, to identify a token. */
const DISPLAY_PREFIX_LENGTH = 12;

/** Usable (unrevoked, unexpired) tokens one user may hold in one organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Raised when a user already holds `MAX_USABLE_TOKENS` usable tokens. */
class ApiTokenLimitError extends Error {
  readonly code = "conflict" as const;

  constructor() {
    super(
      `You can hold at most ${MAX_USABLE_TOKENS} active API tokens per organization; revoke one first`,
    );
    this.name = "ApiTokenLimitError";
  }
}

/**
 * Mints a token. The secret is returned here and nowhere else — only its hash
 * is stored, and neither reaches the audit log or the event payload.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);

  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;
  const now = new Date();

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY)),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );
  if (apiToken === null) throw new ApiTokenLimitError();

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

/**
 * A user's tokens in the org, revoked and expired ones included, newest first.
 * Reading someone else's list takes `admin` or above.
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

/**
 * Revokes a token. Idempotent: revoking an already-revoked token returns it
 * unchanged, without a second audit row.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const now = toIsoTimestamp(new Date());
  const revoked = await apiTokenRepo.revokeApiToken(orgId, tokenId, now);
  // Lost a race with another revocation: theirs stands, and theirs is audited.
  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

